import javax.tools.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Runs the production shutter transaction against controlled Camera2 callback ordering.
 * DngCreator is a fixture: these tests verify pairing/cleanup, not a phone's RAW support.
 */
public final class RawLifecycleRegression {
    static void write(Path root,List<String> files,String name,String text)throws IOException{Path path=root.resolve(name);Files.createDirectories(path.getParent());Files.write(path,text.getBytes(StandardCharsets.UTF_8));files.add(path.toString());}
    public static void main(String[] args)throws Exception{
        Path root=Paths.get(args[0]),dir=root.resolve("build/raw-lifecycle-tests"),classes=dir.resolve("classes");Files.createDirectories(classes);List<String> files=new ArrayList<>();
        write(dir,files,"android/hardware/camera2/CameraCharacteristics.java","package android.hardware.camera2;public class CameraCharacteristics {}");
        write(dir,files,"android/hardware/camera2/CaptureResult.java","package android.hardware.camera2;public class CaptureResult {public static final class Key<T>{}public static final Key<Long> SENSOR_TIMESTAMP=new Key<>();private final Long timestamp;public CaptureResult(Long t){timestamp=t;}@SuppressWarnings(\"unchecked\") public <T>T get(Key<T> key){return (T)timestamp;}}");
        write(dir,files,"android/media/Image.java","package android.media;public class Image implements AutoCloseable {public boolean closed;public int closes;private final long time;public Image(long t){time=t;}public long getTimestamp(){if(closed)throw new IllegalStateException(\"image closed\");return time;}public void close(){closed=true;closes++;}}");
        write(dir,files,"android/os/Handler.java","package android.os;import java.util.*;public class Handler {private final List<Runnable> delayed=new ArrayList<>();public boolean post(Runnable r){r.run();return true;}public boolean postDelayed(Runnable r,long ms){delayed.add(r);return true;}public void timeout(){List<Runnable> all=new ArrayList<>(delayed);delayed.clear();for(Runnable r:all)r.run();}}");
        write(dir,files,"android/hardware/camera2/DngCreator.java","package android.hardware.camera2;import java.io.*;import android.media.Image;public class DngCreator implements AutoCloseable {public static boolean fail;public static int orientation,writes;public DngCreator(CameraCharacteristics c,CaptureResult r){}public DngCreator setOrientation(int o){orientation=o;return this;}public DngCreator setDescription(String s){return this;}public void writeImage(OutputStream out,Image image)throws IOException{if(image.closed)throw new IOException(\"closed RAW image\");writes++;out.write(new byte[]{73,73,42,0});if(fail)throw new IOException(\"simulated encoder failure\");}public void close(){}}");
        write(dir,files,"com/silverroom/camera/RawTransactionProbe.java",probe());
        files.add(root.resolve("src/com/silverroom/camera/RawCapture.java").toString());files.add(root.resolve("src/com/silverroom/camera/RawPolicy.java").toString());
        List<String> options=new ArrayList<>(Arrays.asList("--release","8","-encoding","UTF-8","-d",classes.toString()));options.addAll(files);if(ToolProvider.getSystemJavaCompiler().run(null,null,null,options.toArray(new String[0]))!=0)throw new AssertionError("RAW callback fixture compilation failed");
        try(URLClassLoader loader=new URLClassLoader(new URL[]{classes.toUri().toURL()},null)){try{List<?> passed=(List<?>)loader.loadClass("com.silverroom.camera.RawTransactionProbe").getMethod("run",File.class).invoke(null,dir.toFile());for(Object label:passed)System.out.println("PASS "+label);System.out.println("ALL "+passed.size()+" PRODUCTION RAW TRANSACTION TESTS PASSED");}catch(java.lang.reflect.InvocationTargetException failure){throw new AssertionError("Production RAW transaction failed",failure.getCause());}}
    }
    static String probe(){return
        "package com.silverroom.camera;import android.hardware.camera2.*;import android.media.Image;import android.os.Handler;import java.io.*;import java.util.*;import java.util.concurrent.*;public final class RawTransactionProbe {"+
        "static final List<String> passed=new ArrayList<>();static File cache;static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);passed.add(name);}static class Exec extends AbstractExecutorService{boolean queued;List<Runnable> work=new ArrayList<>();public void execute(Runnable r){if(queued)work.add(r);else r.run();}void flush(){for(Runnable r:new ArrayList<>(work))r.run();work.clear();}public void shutdown(){}public List<Runnable> shutdownNow(){return work;}public boolean isShutdown(){return false;}public boolean isTerminated(){return false;}public boolean awaitTermination(long t,TimeUnit u){return true;}}"+
        "static class Shot implements RawCapture.Complete {int calls;byte[] jpeg;File dng;CaptureResult result;String note;public void done(byte[] j,File d,CaptureResult r,String n){calls++;jpeg=j;dng=d;result=r;note=n;}void clean(){if(dng!=null)dng.delete();}}static RawCapture bundle(Exec e,Handler h,Shot s,boolean raw){return new RawCapture(cache,new CameraCharacteristics(),e,h,90,raw,\"RAW unavailable\",s);}static long files(){return cache.listFiles((d,n)->n.startsWith(\"fancy-raw-\")).length;}"+
        "public static List<String> run(File dir)throws Exception {cache=new File(dir,\"transactions-\"+System.nanoTime());cache.mkdir();String[] orders={\"JRI\",\"JIR\",\"RJI\",\"RIJ\",\"IJR\",\"IRJ\"};for(String order:orders){Shot s=new Shot();Handler h=new Handler();RawCapture b=bundle(new Exec(),h,s,true);Image raw=new Image(100);CaptureResult result=new CaptureResult(100L);byte[] jpeg={7,8};for(char c:order.toCharArray()){if(c=='J')b.jpeg(jpeg);if(c=='R')b.result(result);if(c=='I')b.image(raw);}h.timeout();check(s.calls==1&&s.jpeg==jpeg&&s.result==result&&s.dng!=null&&s.dng.length()==4&&raw.closes==1&&DngCreator.orientation==6,\"RAW callback order \"+order+\" yields one timestamp-paired DNG and closes its Image\");s.clean();}"+
        "Shot missing=new Shot();Handler h=new Handler();RawCapture b=bundle(new Exec(),h,missing,true);b.jpeg(new byte[]{1});b.result(new CaptureResult(100L));h.timeout();check(missing.calls==1&&missing.dng==null&&missing.note.contains(\"JPEG\"),\"Missing RAW times out to a usable JPEG\");"+
        "Shot late=new Shot();h=new Handler();b=bundle(new Exec(),h,late,true);Image abandoned=new Image(100);b.image(abandoned);h.timeout();b.jpeg(new byte[]{2});check(late.calls==1&&late.result==null&&late.dng==null&&abandoned.closed,\"Late JPEG after missing metadata still completes and releases held RAW\");"+
        "Shot mismatch=new Shot();h=new Handler();b=bundle(new Exec(),h,mismatch,true);Image wrong=new Image(101);b.image(wrong);b.result(new CaptureResult(100L));b.jpeg(new byte[]{3});check(mismatch.calls==1&&mismatch.dng==null&&wrong.closed&&mismatch.note.contains(\"时间戳\")&&files()==0,\"Mismatched sensor timestamps never produce a mislabeled DNG\");"+
        "DngCreator.fail=true;Shot failed=new Shot();b=bundle(new Exec(),new Handler(),failed,true);Image broken=new Image(100);b.image(broken);b.result(new CaptureResult(100L));b.jpeg(new byte[]{4});DngCreator.fail=false;check(failed.calls==1&&failed.dng==null&&failed.jpeg[0]==4&&broken.closed&&files()==0,\"DNG encoder failure removes partial output while preserving JPEG\");"+
        "Shot cancelled=new Shot();h=new Handler();b=bundle(new Exec(),h,cancelled,true);Image held=new Image(100);b.image(held);b.cancel();h.timeout();b.jpeg(new byte[]{5});check(cancelled.calls==0&&held.closes==1&&files()==0,\"Lifecycle cancellation releases an unencoded RAW without delivering a stale photo\");"+
        "Exec queued=new Exec();queued.queued=true;Shot pending=new Shot();b=bundle(queued,new Handler(),pending,true);Image encoding=new Image(100);b.jpeg(new byte[]{6});b.result(new CaptureResult(100L));b.image(encoding);b.cancel();queued.flush();check(pending.calls==0&&encoding.closed&&files()==0,\"Cancellation during queued encoding removes its DNG and suppresses callback\");"+
        "Shot rejected=new Shot();b=bundle(new Exec(),new Handler(),rejected,true);Image unused=new Image(100);b.image(unused);b.withoutRaw(\"configuration rejected\");b.result(new CaptureResult(100L));b.jpeg(new byte[]{7});check(rejected.calls==1&&rejected.dng==null&&unused.closed&&rejected.note.equals(\"configuration rejected\"),\"Session rejection closes held RAW and saves JPEG with its reason\");"+
        "Shot plain=new Shot();h=new Handler();b=bundle(new Exec(),h,plain,false);b.jpeg(new byte[]{8});h.timeout();Image extra=new Image(100);b.image(extra);b.result(new CaptureResult(100L));check(plain.calls==1&&plain.dng==null&&extra.closed,\"JPEG-only capture tolerates absent metadata and closes unexpected late RAW\");"+
        "Shot duplicates=new Shot();b=bundle(new Exec(),new Handler(),duplicates,true);Image first=new Image(100),second=new Image(100);b.image(first);b.image(second);b.result(new CaptureResult(100L));b.jpeg(new byte[]{9});b.jpeg(new byte[]{10});check(duplicates.calls==1&&duplicates.jpeg[0]==9&&first.closed&&second.closed,\"Duplicate callbacks cannot overwrite or deliver a second photo\");duplicates.clean();check(files()==0,\"Every completed, failed and cancelled fixture leaves no abandoned RAW temp file\");return passed;}}";
    }
}
